[CmdletBinding()]
param([switch]$RunProcessEvidence,[switch]$UseRealProcessAdapter)
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
. (Join-Path (Split-Path -Parent $PSScriptRoot) 'demo\Invoke-SumiGuardManagedAssessmentVerificationDemo.ps1')
$script:SumiGuardStopGraceMilliseconds=250
$script:SumiGuardStreamDrainMilliseconds=250
function Get-SumiGuardEvidenceProperty($Value,[string]$Name){if($null -eq $Value -or $null -eq $Value.PSObject.Properties[$Name]){return $null};$Value.PSObject.Properties[$Name].Value}
function Get-SumiGuardTaskCapture($Task,[int]$TimeoutMilliseconds){
 if($null -eq $Task){return [pscustomobject]@{completed=$false;value=$null;failure='TASK_NOT_CREATED'}}
 try{if(-not $Task.Wait($TimeoutMilliseconds)){return [pscustomobject]@{completed=$false;value=$null;failure='TASK_NOT_COMPLETED'}};if($Task.IsCanceled){return [pscustomobject]@{completed=$false;value=$null;failure='TASK_CANCELED'}};if($Task.IsFaulted){return [pscustomobject]@{completed=$false;value=$null;failure='TASK_FAULTED'}};[pscustomobject]@{completed=$true;value=$Task.GetAwaiter().GetResult();failure=$null}}catch{[pscustomobject]@{completed=$false;value=$null;failure='TASK_WAIT_OR_READ_FAILED'}}
}
function New-SumiGuardManagedProcessEvidencePlan {
[Diagnostics.CodeAnalysis.SuppressMessageAttribute('PSUseShouldProcessForStateChangingFunctions', '', Justification='Creates only an in-memory plan and does not change external state or start a process.')]
param([Parameter(Mandatory=$true)][ValidatePattern('^[0-9a-f]{32}$')][string]$CorrelationId,[ValidateSet('NORMAL','NONZERO_EXIT','TIMEOUT')][string]$Scenario='NORMAL')
 $base=Get-SumiGuardManagedPowerShellDemoConfiguration;$body=switch($Scenario){'NONZERO_EXIT'{"[Console]::Out.WriteLine('SUMI_GUARD_PROCESS_EVIDENCE:$CorrelationId'); exit 7"}'TIMEOUT'{"Start-Sleep -Seconds 10; [Console]::Out.WriteLine('SUMI_GUARD_PROCESS_EVIDENCE:$CorrelationId')"}default{"[Console]::Out.WriteLine('SUMI_GUARD_PROCESS_EVIDENCE:$CorrelationId')"}};$arguments='-Version 5.1 -NoLogo -NoProfile -NonInteractive -EncodedCommand '+[Convert]::ToBase64String([Text.Encoding]::Unicode.GetBytes($body));$si=New-SumiGuardManagedPowerShellStartInfo;$si.Arguments=$arguments;$timeout=if($Scenario -ceq 'TIMEOUT'){1000}else{$base.timeout_milliseconds};$cfg=[pscustomobject]@{executable_path=$base.executable_path;assessment_command_text=$body;launch_command_text=$body;expected_interpreter_version=$null;argument_line=$arguments;timeout_milliseconds=$timeout};[pscustomobject]@{scenario=$Scenario;body=$body;arguments=$arguments;expected_stdout="SUMI_GUARD_PROCESS_EVIDENCE:$CorrelationId`r`n";start_info=$si;configuration=$cfg;arguments_verified=($si.Arguments -ceq $arguments);body_verified=($cfg.assessment_command_text -ceq $body -and $cfg.launch_command_text -ceq $body)}
}
function New-SumiGuardAdapterFailureEvidence {
[Diagnostics.CodeAnalysis.SuppressMessageAttribute('PSUseShouldProcessForStateChangingFunctions', '', Justification='Creates only an in-memory evidence object and does not change external state or start a process.')]
param([string]$Stage,[Exception]$Exception,[bool]$Started=$false)
 [pscustomobject]@{process_started=$Started;execution_id=$null;observed_executable_path=$null;process_handle_obtained=$null;observed_pid=$null;observed_start_time_utc=$null;pid_obtained=$null;start_time_obtained=$null;executable_path_obtained=$null;correlation_id_matches=$null;child_exit_code=$null;timed_out=$null;stdout_matches_expected=$null;termination_status=if($Started){'ADAPTER_EXCEPTION'}else{'NOT_STARTED'};process_exit_confirmed=if($Started){$false}else{$null};kill_attempted=$false;kill_succeeded=$null;stdout_capture_completed=$false;stderr_capture_completed=$false;stdout_capture_failure='NOT_CAPTURED';stderr_capture_failure='NOT_CAPTURED';child_execution_status=if($Started){'ADAPTER_FAILED'}else{'NOT_STARTED'};child_execution_succeeded=if($Started){$false}else{$null};child_execution_reason_code=if($Started){'ADAPTER_EXCEPTION'}else{'NOT_STARTED'};adapter_stage=$Stage;adapter_exception_type=if($null -eq $Exception){$null}else{$Exception.GetType().FullName};adapter_exception_hresult=if($null -eq $Exception){$null}else{$Exception.HResult}}
}
function Invoke-SumiGuardManagedProcessEvidenceAdapterCore {
 param([Parameter(Mandatory=$true)]$Plan,[Parameter(Mandatory=$true)][ValidatePattern('^[0-9a-f]{32}$')][string]$CorrelationId,[AllowNull()][scriptblock]$ProcessFactory=$null)
 if(-not $Plan.arguments_verified -or -not $Plan.body_verified){return New-SumiGuardAdapterFailureEvidence -Stage 'PLAN_UNVERIFIED' -Exception $null}
 $process=$null;$started=$false;$handleHeld=$false;$stage='PLAN_VALIDATED';$exitConfirmed=$false;$timedOut=$null;$exitCode=$null;$killAttempted=$false;$killSucceeded=$null;$termination='NOT_STARTED';$outTask=$null;$errTask=$null;$out=$null;$err=$null;$adapterException=$null;$observedProcessId=$null;$time=$null;$path=$null;$observationStage=$null;$observationType=$null;$observationHResult=$null
 try{$process=if($null -ne $ProcessFactory){& $ProcessFactory}else{New-Object Diagnostics.Process};$process.StartInfo=$Plan.start_info;$stage='PROCESS_START_ATTEMPT';$script:SumiGuardProcessStartAttempts++;if(-not $process.Start()){return New-SumiGuardAdapterFailureEvidence -Stage $stage -Exception $null};$started=$true;$script:SumiGuardProcessStartSuccesses++;$stage='PROCESS_HANDLE_ACQUISITION';$nativeHandle=$process.Handle;if($nativeHandle -eq [IntPtr]::Zero -or $nativeHandle -eq [IntPtr](-1)){throw [InvalidOperationException]::new('Process returned an invalid native handle.')};$handleHeld=$true;# Capture identity from the held Process handle before waiting. Never reread it after exit.
  try{$observedProcessId=[int]$process.Id}catch{$observationStage='OBSERVE_PID';$observationType=$_.Exception.GetType().FullName;$observationHResult=$_.Exception.HResult};try{$time=$process.StartTime.ToUniversalTime().ToString('o')}catch{$observationStage='OBSERVE_START_TIME';$observationType=$_.Exception.GetType().FullName;$observationHResult=$_.Exception.HResult};try{$path=[string]$process.MainModule.FileName}catch{$observationStage='OBSERVE_MAIN_MODULE';$observationType=$_.Exception.GetType().FullName;$observationHResult=$_.Exception.HResult};$stage='STREAM_CAPTURE';$outTask=$process.StandardOutput.ReadToEndAsync();$errTask=$process.StandardError.ReadToEndAsync();$stage='WAIT_FOR_EXIT'
  if($process.WaitForExit([int]$Plan.configuration.timeout_milliseconds)){$exitConfirmed=$true;$timedOut=$false;$termination='EXITED_NORMALLY';try{$reportedExitCode=$process.ExitCode;if($null -ne $reportedExitCode){$exitCode=[int]$reportedExitCode}}catch{$observationStage='OBSERVE_EXIT_CODE';$observationType=$_.Exception.GetType().FullName;$observationHResult=$_.Exception.HResult}}else{$timedOut=$true;$killAttempted=$true;try{$process.Kill();$killSucceeded=$true}catch{$killSucceeded=$false};try{$exitConfirmed=[bool]$process.WaitForExit($script:SumiGuardStopGraceMilliseconds)}catch{$exitConfirmed=$false};if($exitConfirmed -and $killSucceeded){$termination='KILL_CONFIRMED'}elseif($exitConfirmed){$termination='EXIT_CONFIRMED_AFTER_KILL_FAILURE'}elseif($killSucceeded){$termination='EXIT_NOT_CONFIRMED'}else{$termination='KILL_FAILED'}}
  if($exitConfirmed){$out=Get-SumiGuardTaskCapture $outTask $script:SumiGuardStreamDrainMilliseconds;$err=Get-SumiGuardTaskCapture $errTask $script:SumiGuardStreamDrainMilliseconds}else{$out=[pscustomobject]@{completed=$false;value=$null;failure='EXIT_NOT_CONFIRMED'};$err=$out}
 }catch{$adapterException=$_.Exception}finally{if($null -ne $process -and $started -and -not $exitConfirmed -and -not $killAttempted){$killAttempted=$true;try{$process.Kill();$killSucceeded=$true}catch{$killSucceeded=$false};try{$exitConfirmed=[bool]$process.WaitForExit($script:SumiGuardStopGraceMilliseconds)}catch{$exitConfirmed=$false};if($exitConfirmed -and $killSucceeded){$termination='KILL_CONFIRMED'}elseif(-not $exitConfirmed -and $killSucceeded){$termination='EXIT_NOT_CONFIRMED'}elseif(-not $exitConfirmed){$termination='KILL_FAILED'}};if($null -ne $process){try{$process.Dispose()}catch{# Ignore disposal failures: do not replace existing results, count as exit evidence, or expose exception details.
 [void]$_.Exception}}}
 if($null -ne $adapterException){return New-SumiGuardAdapterFailureEvidence -Stage $stage -Exception $adapterException -Started $started};$stdoutMatches=if($out.completed){$out.value -ceq $Plan.expected_stdout}else{$null};$match=if($out.completed){[regex]::Match($out.value,'(?m)^SUMI_GUARD_PROCESS_EVIDENCE:([0-9a-f]{32})\r?$')}else{$null};$childId=if($null -ne $match -and $match.Success){$match.Groups[1].Value}else{$null};$idMatches=if($null -ne $childId){$childId -ceq $CorrelationId}else{$null}
 if(-not $exitConfirmed){$childStatus='EXIT_NOT_CONFIRMED';$success=$false;$reason='EXIT_NOT_CONFIRMED'}elseif($timedOut){$childStatus='TIMED_OUT';$success=$false;$reason='TIMED_OUT'}elseif(-not $out.completed -or -not $err.completed){$childStatus='OUTPUT_CAPTURE_INCOMPLETE';$success=$false;$reason='OUTPUT_CAPTURE_INCOMPLETE'}elseif($null -eq $exitCode){$childStatus='EXIT_CODE_UNAVAILABLE';$success=$false;$reason='EXIT_CODE_UNAVAILABLE'}elseif($exitCode -ne 0){$childStatus='NONZERO_EXIT';$success=$false;$reason='NONZERO_EXIT'}elseif($stdoutMatches -ne $true){$childStatus='OUTPUT_MISMATCH';$success=$false;$reason='OUTPUT_MISMATCH'}else{$childStatus='SUCCEEDED';$success=$true;$reason='SUCCEEDED'}
 [pscustomobject]@{process_started=$started;execution_id=$childId;observed_executable_path=$path;process_handle_obtained=if($handleHeld){$true}else{$null};observed_pid=$observedProcessId;observed_start_time_utc=$time;pid_obtained=if($null -ne $observedProcessId){$true}else{$null};start_time_obtained=if($null -ne $time){$true}else{$null};executable_path_obtained=if($null -ne $path){$true}else{$null};correlation_id_matches=$idMatches;child_exit_code=$exitCode;timed_out=$timedOut;stdout_matches_expected=$stdoutMatches;termination_status=$termination;process_exit_confirmed=$exitConfirmed;kill_attempted=$killAttempted;kill_succeeded=$killSucceeded;stdout_capture_completed=$out.completed;stderr_capture_completed=$err.completed;stdout_capture_failure=$out.failure;stderr_capture_failure=$err.failure;child_execution_status=$childStatus;child_execution_succeeded=$success;child_execution_reason_code=$reason;adapter_stage=if($null -eq $observationStage){'COMPLETED'}else{$observationStage};adapter_exception_type=$observationType;adapter_exception_hresult=$observationHResult}
}
function Invoke-SumiGuardManagedBuiltInProcessEvidenceAdapter {
 param([Parameter(Mandatory=$true)]$Plan,[Parameter(Mandatory=$true)][ValidatePattern('^[0-9a-f]{32}$')][string]$CorrelationId)
 # Production-only path: constructs Diagnostics.Process itself.  No callback or factory is accepted here.
 Invoke-SumiGuardManagedProcessEvidenceAdapterCore -Plan $Plan -CorrelationId $CorrelationId
}
function Invoke-SumiGuardManagedTestProcessEvidenceAdapter {
 param([Parameter(Mandatory=$true)]$Plan,[Parameter(Mandatory=$true)][ValidatePattern('^[0-9a-f]{32}$')][string]$CorrelationId,[Parameter(Mandatory=$true)][scriptblock]$ProcessFactoryOverride)
 # Test seam: returns diagnostic evidence only; callers must never attest it as PROCESS_CONFIRMED.
 Invoke-SumiGuardManagedProcessEvidenceAdapterCore -Plan $Plan -CorrelationId $CorrelationId -ProcessFactory $ProcessFactoryOverride
}
function Invoke-SumiGuardManagedRealProcessEvidenceAdapter {
 param([Parameter(Mandatory=$true)]$Plan,[Parameter(Mandatory=$true)][ValidatePattern('^[0-9a-f]{32}$')][string]$CorrelationId,[AllowNull()][scriptblock]$ProcessFactoryOverride=$null)
 # Compatibility entry point.  A supplied factory is always the untrusted test seam.
 if($null -ne $ProcessFactoryOverride){return Invoke-SumiGuardManagedTestProcessEvidenceAdapter -Plan $Plan -CorrelationId $CorrelationId -ProcessFactoryOverride $ProcessFactoryOverride}
 return Invoke-SumiGuardManagedBuiltInProcessEvidenceAdapter -Plan $Plan -CorrelationId $CorrelationId
}
function Invoke-SumiGuardManagedProcessEvidenceConnection {
 [CmdletBinding()]param([Parameter(Mandatory=$true)][ValidatePattern('^[0-9a-f]{32}$')][string]$CorrelationId,[ValidateSet('NORMAL','NONZERO_EXIT','TIMEOUT')][string]$Scenario='NORMAL',[AllowNull()]$ConfigurationOverride=$null,[AllowNull()]$VerificationOverride=$null,[AllowNull()][scriptblock]$ProcessObserver=$null,[switch]$RunProcess,[switch]$UseRealProcessAdapter,[AllowNull()]$PlanOverride=$null,[AllowNull()][scriptblock]$ProcessAdapterOverride=$null,[AllowNull()][scriptblock]$ProcessFactoryOverride=$null)
 $script:SumiGuardObserverInvocations=0;$script:SumiGuardProcessStartAttempts=0;$script:SumiGuardProcessStartSuccesses=0;$script:SumiGuardAdapterEvidence=$null;$plan=if($null -ne $PlanOverride){$PlanOverride}else{New-SumiGuardManagedProcessEvidencePlan -CorrelationId $CorrelationId -Scenario $Scenario};$ok=([bool]$plan.arguments_verified -and [bool]$plan.body_verified);$cfg=if($null -ne $ConfigurationOverride){$ConfigurationOverride}else{$plan.configuration};$run=([bool]$RunProcess -and $ok);$use=([bool]($run -and $UseRealProcessAdapter -and $null -eq $ProcessObserver));$useBuiltInProductionAdapter=([bool]($use -and $null -eq $ProcessAdapterOverride -and $null -eq $ProcessFactoryOverride));$adapterOverrideForObserver=$ProcessAdapterOverride;$factoryOverrideForObserver=$ProcessFactoryOverride;$observer={$script:SumiGuardObserverInvocations++;try{$e=if($null -ne $ProcessObserver){& $ProcessObserver $CorrelationId}elseif($useBuiltInProductionAdapter){Invoke-SumiGuardManagedBuiltInProcessEvidenceAdapter -Plan $plan -CorrelationId $CorrelationId}elseif($use){if($null -ne $adapterOverrideForObserver){& $adapterOverrideForObserver $plan $CorrelationId}else{Invoke-SumiGuardManagedTestProcessEvidenceAdapter -Plan $plan -CorrelationId $CorrelationId -ProcessFactoryOverride $factoryOverrideForObserver}}else{$null};if($useBuiltInProductionAdapter -and $null -ne $e){$verificationModule=Get-Module -Name 'SumiGuard.ManagedAssessmentVerification';if($null -eq $verificationModule){throw 'Managed verification module is unavailable for internal evidence attestation.'};& $verificationModule {param($Evidence) Register-SumiGuardTrustedPostExecutionEvidence -Evidence $Evidence} $e};$script:SumiGuardAdapterEvidence=$e;return $e}catch{$e=New-SumiGuardAdapterFailureEvidence -Stage 'OBSERVER_INVOCATION' -Exception $_.Exception;$script:SumiGuardAdapterEvidence=$e;return $e}};$report=Invoke-SumiGuardManagedAssessmentVerificationConnection -ConfigurationOverride $cfg -VerificationOverride $VerificationOverride -AssessmentExecutionId $CorrelationId -PlannedExecutionId $CorrelationId -RequestDryStart:$run -TestDoubleStart $observer;$e=$script:SumiGuardAdapterEvidence
 [pscustomobject]@{assessment_status=$report.assessment_status;assessment_reason_code=$report.assessment_reason_code;reconciliation_status=$report.reconciliation_status;reconciliation_reason_code=$report.reconciliation_reason_code;process_confirmation_status=$report.process_confirmation_status;process_confirmation_reason_code=$report.process_confirmation_reason_code;execution_status=$report.execution_status;child_execution_status=(Get-SumiGuardEvidenceProperty $e 'child_execution_status');child_execution_succeeded=(Get-SumiGuardEvidenceProperty $e 'child_execution_succeeded');child_execution_reason_code=(Get-SumiGuardEvidenceProperty $e 'child_execution_reason_code');execution_start_count=$report.execution_start_count;execution_start_count_meaning='OBSERVER_INVOCATIONS_REPORTED_BY_EXISTING_CONNECTION';storage_status='NOT_ATTEMPTED';plan_body_verified=$plan.body_verified;plan_arguments_verified=$plan.arguments_verified;adapter_stage=(Get-SumiGuardEvidenceProperty $e 'adapter_stage');adapter_exception_type=(Get-SumiGuardEvidenceProperty $e 'adapter_exception_type');adapter_exception_hresult=(Get-SumiGuardEvidenceProperty $e 'adapter_exception_hresult');observer_invocation_count=$script:SumiGuardObserverInvocations;process_start_attempt_count=$script:SumiGuardProcessStartAttempts;process_start_success_count=$script:SumiGuardProcessStartSuccesses;child_exit_code=(Get-SumiGuardEvidenceProperty $e 'child_exit_code');timed_out=(Get-SumiGuardEvidenceProperty $e 'timed_out');stdout_matches_expected=(Get-SumiGuardEvidenceProperty $e 'stdout_matches_expected');process_handle_obtained=(Get-SumiGuardEvidenceProperty $e 'process_handle_obtained');pid_obtained=(Get-SumiGuardEvidenceProperty $e 'pid_obtained');start_time_obtained=(Get-SumiGuardEvidenceProperty $e 'start_time_obtained');executable_path_obtained=(Get-SumiGuardEvidenceProperty $e 'executable_path_obtained');correlation_id_matches=(Get-SumiGuardEvidenceProperty $e 'correlation_id_matches');correlation_returned=(Get-SumiGuardEvidenceProperty $e 'correlation_id_matches');termination_status=(Get-SumiGuardEvidenceProperty $e 'termination_status');process_exit_confirmed=(Get-SumiGuardEvidenceProperty $e 'process_exit_confirmed');kill_attempted=(Get-SumiGuardEvidenceProperty $e 'kill_attempted');kill_succeeded=(Get-SumiGuardEvidenceProperty $e 'kill_succeeded');stdout_capture_completed=(Get-SumiGuardEvidenceProperty $e 'stdout_capture_completed');stderr_capture_completed=(Get-SumiGuardEvidenceProperty $e 'stderr_capture_completed');stdout_capture_failure=(Get-SumiGuardEvidenceProperty $e 'stdout_capture_failure');stderr_capture_failure=(Get-SumiGuardEvidenceProperty $e 'stderr_capture_failure')}
}
if($MyInvocation.InvocationName -cne '.'){ $id=[Guid]::NewGuid().ToString('N');$r=Invoke-SumiGuardManagedProcessEvidenceConnection -CorrelationId $id -RunProcess:$RunProcessEvidence -UseRealProcessAdapter:$UseRealProcessAdapter;$r|ConvertTo-Json -Compress;# Compatibility: confirmation is identity evidence, not child-success evidence.
 if($RunProcessEvidence -and $UseRealProcessAdapter -and $r.process_confirmation_status -cne 'PROCESS_CONFIRMED'){exit 1}}
